WITH with_dims AS (SELECT a.id, a.store_id, a.product_id, a.quantity, p.product_name, p.brand FROM inventory a JOIN products p ON a.product_id = p.id WHERE p.brand != 'Acme') SELECT CASE WHEN quantity >= 182 THEN 'PREMIUM' ELSE 'STANDARD' END AS quantity_tier, ROUND(SUM(quantity) / NULLIF(COUNT(CASE WHEN brand = 'Globex' THEN 1 END), 0), 2) AS quantity_per_globex, SUM(CASE WHEN brand = 'Initech' THEN quantity ELSE 0 END) AS initech_quantity, ROUND(AVG(quantity), 2) AS avg_quantity, STDDEV_SAMP(quantity) AS quantity_stddev FROM with_dims GROUP BY quantity_tier ORDER BY quantity_stddev
